challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The UPF is the source of data plane degradation, resulting in significant media packet loss.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "From rtpengine to the suspect upf, to test the N6 media path.",
          "expected_if_hypothesis_holds": "High latency or packet loss is observed.",
          "falsifying_observation": "No significant latency or packet loss is observed.",
          "conflates_with": [
            "the network path between rtpengine and upf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From rtpengine to the smf, to create a baseline for the network path.",
          "expected_if_hypothesis_holds": "No significant latency or packet loss is observed, suggesting the issue is specific to the UPF and not the general network path from rtpengine.",
          "falsifying_observation": "High latency or packet loss is observed, suggesting a broader network issue rather than a UPF-specific one, weakening the hypothesis.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check UPF's accounting of GTP packets on N3 uplink and downlink over a 120s window.",
          "expected_if_hypothesis_holds": "A deviation in `upf.gtp_indatapktn3upf_per_ue` or `upf.gtp_outdatapktn3upf_per_ue` is observed, such as a drop or zero value, corresponding to the packet loss.",
          "falsifying_observation": "Both `upf.gtp_indatapktn3upf_per_ue` and `upf.gtp_outdatapktn3upf_per_ue` are within their typical healthy range.",
          "conflates_with": []
        }
      ],
      "notes": "This plan uses a paired-probe approach (measure_rtt) to distinguish between a faulty UPF and a faulty network path between the media anchor (rtpengine) and the UPF. It adds a direct metric check on the UPF's own counters as a third, non-compositional data point."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "The RTPEngine is the source of the data plane degradation, dropping packets on its egress.",
      "primary_suspect_nf": "rtpengine",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check for errors reported by rtpengine's relay over a 120s window.",
          "expected_if_hypothesis_holds": "A spike is observed in the `rtpengine.errors_per_second` metric.",
          "falsifying_observation": "The `rtpengine.errors_per_second` metric remains at its healthy baseline of zero.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From upf to the suspect rtpengine, to test the N6 media path.",
          "expected_if_hypothesis_holds": "High latency or packet loss is observed.",
          "falsifying_observation": "No significant latency or packet loss is observed.",
          "conflates_with": [
            "the network path between upf and rtpengine"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From upf to the smf, to create a baseline for the network path.",
          "expected_if_hypothesis_holds": "No significant latency or packet loss is observed, suggesting the issue is specific to rtpengine and not the general network path from upf.",
          "falsifying_observation": "High latency or packet loss is observed, suggesting a broader network issue rather than an rtpengine-specific one.",
          "conflates_with": []
        }
      ],
      "notes": "This plan first checks for direct evidence of rtpengine-internal errors. It then uses a paired-probe approach (measure_rtt) to test the network path to rtpengine, separating path-level problems from issues at the rtpengine container itself."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "The HSS is unresponsive, causing downstream call setup failures across the IMS.",
      "primary_suspect_nf": "pyhss",
      "probes": [
        {
          "tool": "query_subscriber",
          "args_hint": "Query for a known test subscriber IMSI (e.g., 'imsi-001010000000001') to check HSS responsiveness to Diameter requests.",
          "expected_if_hypothesis_holds": "The query times out or returns an error.",
          "falsifying_observation": "The query returns a valid subscriber profile successfully and quickly.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From icscf to the suspect pyhss, to test the Cx interface path.",
          "expected_if_hypothesis_holds": "High latency or packet loss is observed.",
          "falsifying_observation": "No significant latency or packet loss is observed.",
          "conflates_with": [
            "the network path between icscf and pyhss"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "From icscf to the scscf, to create a baseline for the IMS network.",
          "expected_if_hypothesis_holds": "No significant latency or packet loss is observed, suggesting the issue is specific to pyhss and not the general network path from icscf.",
          "falsifying_observation": "High latency or packet loss is observed, suggesting a broader IMS network issue rather than a pyhss-specific one.",
          "conflates_with": []
        }
      ],
      "notes": "This plan tests the HSS at two layers: an application-level query to check the Diameter service, and a paired network-level probe (measure_rtt) to isolate network path issues from container-level unresponsiveness on the Cx interface. This covers the 'no KB candidates' gap for this hypothesis."
    }
  ]
}
